const keywords = ['قوى','بلدي','ناجز','أبشر','مساند','مدد','وزارة الموارد','الجوازات','وزارة العدل','تأشيرة','إقامة','رخصة','سجل تجاري','الزكاة','الضريبة'];
const seen = new Set();
const results = [];
for (const item of $input.all()) {
  const d = item.json;
  const title = String(d.title || '').trim();
  const link = String(d.link || '').trim();
  if (!title || !link) continue;
  const key = title.toLocaleLowerCase('ar').replace(/\s+/g,' ');
  if (seen.has(key)) continue;
  seen.add(key);
  const matched = keywords.filter(k => key.includes(k));
  if (!matched.length) continue;
  results.push({json:{title,discovery_url:link,source_name:String(d.creator || d.author || 'Google News RSS'),published_at:d.isoDate || d.pubDate || null,matched_keywords:matched,relevance_score:matched.length,verification_status:'UNVERIFIED',publish_allowed:false,next_step:'Find the original official Saudi government source; verify each factual claim and its effective date before creating content.'}});
}
results.sort((a,b)=>b.json.relevance_score-a.json.relevance_score);
return results.slice(0,15);
